sugroup=$(/bin/grep -Pi '^\h*auth\h+(?:required|requisite)\h+pam_wheel\.so\h+(?:[^#\n\r]+\h+)?((?!\2)(use_uid\b|group=\H+\b))\h+(?:[^#\n\r]+\h+)?((?!\1)(use_uid\b|group=\H+\b))(\h+.*)?$' /etc/pam.d/su | /bin/awk 'BEGIN { FS = "="} ; { print $2 }'); if [ ! -z $sugroup ]; then /bin/grep $sugroup /etc/group | /bin/awk 'BEGIN { FS = ":" }; { print $4 }' | /bin/awk '{print} END {if (NF == 0) print "pass - group empty"; else print "fail - group not empty"}'; else echo "fail - sugroup not found in /etc/pam.d/su"; fi